-- Load the mock knowledge base. Run from this folder after docs/agents/schema.sql:
--   psql "$DB" -f load.sql
\set ON_ERROR_STOP on
BEGIN;
SET search_path = kb, public;
\copy kb.organisations (id, slug, name, trade, city, tally_version, fy_start, language, created_at) FROM 'csv/organisations.csv' WITH (FORMAT csv, HEADER true)
\copy kb.users (id, organisation_id, name, role, email, phone) FROM 'csv/users.csv' WITH (FORMAT csv, HEADER true)
\copy kb.tally_sync_runs (id, organisation_id, started_at, finished_at, status, last_alter_id, objects_read, error) FROM 'csv/tally_sync_runs.csv' WITH (FORMAT csv, HEADER true)
\copy kb.godowns (id, organisation_id, tally_guid, name) FROM 'csv/godowns.csv' WITH (FORMAT csv, HEADER true)
\copy kb.parties (id, organisation_id, tally_guid, name, kind, tally_group, contact_name, phone, email, gstin, city, area, credit_days, credit_limit, salesperson_id, brand, since) FROM 'csv/parties.csv' WITH (FORMAT csv, HEADER true)
\copy kb.items (id, organisation_id, tally_guid, name, stock_group, unit, hsn, gst_rate, standard_cost, standard_rate, reorder_level) FROM 'csv/items.csv' WITH (FORMAT csv, HEADER true)
\copy kb.vouchers (id, organisation_id, tally_guid, alter_id, voucher_type, number, date, party_id, amount, tax_amount, narration) FROM 'csv/vouchers.csv' WITH (FORMAT csv, HEADER true)
\copy kb.voucher_lines (id, organisation_id, voucher_id, line_no, item_id, godown_id, qty, rate, amount) FROM 'csv/voucher_lines.csv' WITH (FORMAT csv, HEADER true)
\copy kb.bills (id, organisation_id, party_id, direction, bill_ref, bill_date, due_date, amount, pending_amount, voucher_id) FROM 'csv/bills.csv' WITH (FORMAT csv, HEADER true)
\copy kb.bill_allocations (id, organisation_id, bill_id, voucher_id, amount, date) FROM 'csv/bill_allocations.csv' WITH (FORMAT csv, HEADER true)
\copy kb.stock_balances (organisation_id, item_id, godown_id, as_of, qty, value) FROM 'csv/stock_balances.csv' WITH (FORMAT csv, HEADER true)
\copy kb.customer_profiles (party_id, organisation_id, grade, previous_grade, avg_days_late, usual_pay_day, promises_made, promises_kept, sales_12m, sales_90d, outstanding, overdue, oldest_overdue_days, last_order_on, avg_order_gap_days, trend, suggested_credit_limit, reasons, computed_at) FROM 'csv/customer_profiles.csv' WITH (FORMAT csv, HEADER true)
\copy kb.item_metrics (item_id, organisation_id, sold_7d, sold_28d, per_day, stock_qty, stock_value, days_left, last_sale_on, idle_days, reorder_qty, status, computed_at) FROM 'csv/item_metrics.csv' WITH (FORMAT csv, HEADER true)
\copy kb.price_points (id, organisation_id, item_id, party_id, source, date, rate, qty) FROM 'csv/price_points.csv' WITH (FORMAT csv, HEADER true)
\copy kb.cash_forecast (organisation_id, week_start, scenario, opening_balance, inflow, outflow, closing_balance, detail, computed_at) FROM 'csv/cash_forecast.csv' WITH (FORMAT csv, HEADER true)
\copy kb.kpi_snapshots (organisation_id, day, metric, value) FROM 'csv/kpi_snapshots.csv' WITH (FORMAT csv, HEADER true)
\copy kb.enquiries (id, organisation_id, party_id, channel, raw_text, received_at, parsed, status, assigned_to) FROM 'csv/enquiries.csv' WITH (FORMAT csv, HEADER true)
\copy kb.quotes (id, organisation_id, number, party_id, enquiry_id, status, created_at, sent_at, opened_at, decided_at, valid_until, subtotal, freight, tax, total, margin_pct, lost_reason, owner_id, sales_voucher_id) FROM 'csv/quotes.csv' WITH (FORMAT csv, HEADER true)
\copy kb.quote_lines (id, organisation_id, quote_id, item_id, qty, rate, last_rate, margin_pct) FROM 'csv/quote_lines.csv' WITH (FORMAT csv, HEADER true)
\copy kb.promises (id, organisation_id, party_id, amount, made_on, due_date, source, status, settled_amount) FROM 'csv/promises.csv' WITH (FORMAT csv, HEADER true)
\copy kb.messages (id, organisation_id, party_id, agent, purpose, channel, language, body, status, created_at, sent_at, entity_type, entity_id) FROM 'csv/messages.csv' WITH (FORMAT csv, HEADER true)
\copy kb.share_links (id, organisation_id, token_hash, purpose, party_id, entity_type, entity_id, created_at, expires_at, first_opened_at, responded_at, response) FROM 'csv/share_links.csv' WITH (FORMAT csv, HEADER true)
\copy kb.rfqs (id, organisation_id, item_id, qty, created_at, status) FROM 'csv/rfqs.csv' WITH (FORMAT csv, HEADER true)
\copy kb.supplier_quotes (id, organisation_id, rfq_id, supplier_id, item_id, rate, delivery_days, received_at, valid_until) FROM 'csv/supplier_quotes.csv' WITH (FORMAT csv, HEADER true)
\copy kb.purchase_orders (id, organisation_id, number, supplier_id, status, created_at, total, purchase_voucher_id) FROM 'csv/purchase_orders.csv' WITH (FORMAT csv, HEADER true)
\copy kb.po_lines (id, organisation_id, po_id, item_id, qty, rate) FROM 'csv/po_lines.csv' WITH (FORMAT csv, HEADER true)
\copy kb.tasks (id, organisation_id, agent, kind, title, detail, entity_type, entity_id, amount, priority, assignee_role, status, created_at, due_at, done_at) FROM 'csv/tasks.csv' WITH (FORMAT csv, HEADER true)
\copy kb.approvals (id, organisation_id, agent, action_type, title, reason, amount, payload, requested_by, requested_at, status, decided_by, decided_at, graph_thread_id) FROM 'csv/approvals.csv' WITH (FORMAT csv, HEADER true)
\copy kb.agent_rules (organisation_id, agent, key, value, updated_by, updated_at) FROM 'csv/agent_rules.csv' WITH (FORMAT csv, HEADER true)
\copy kb.events (id, organisation_id, occurred_at, type, entity_type, entity_id, source, actor, payload) FROM 'csv/events.csv' WITH (FORMAT csv, HEADER true)
\copy kb.event_deliveries (event_id, consumer, status, attempts, processed_at) FROM 'csv/event_deliveries.csv' WITH (FORMAT csv, HEADER true)
\copy kb.item_aliases (id, organisation_id, item_id, alias, source, hits) FROM 'csv/item_aliases.csv' WITH (FORMAT csv, HEADER true)
\copy kb.memories (id, organisation_id, scope_type, scope_id, kind, content, embedding, source, confidence, valid_from, valid_to, created_by) FROM 'csv/memories.csv' WITH (FORMAT csv, HEADER true)
\copy kb.documents (id, organisation_id, kind, title, party_id, received_at, storage_url, text) FROM 'csv/documents.csv' WITH (FORMAT csv, HEADER true)
\copy kb.document_chunks (id, organisation_id, document_id, chunk_no, content, embedding) FROM 'csv/document_chunks.csv' WITH (FORMAT csv, HEADER true)
\copy kb.chat_threads (id, organisation_id, user_id, agent, langgraph_thread_id, created_at, last_message_at) FROM 'csv/chat_threads.csv' WITH (FORMAT csv, HEADER true)
\copy kb.agent_runs (id, organisation_id, agent, trigger_type, trigger_ref, started_at, finished_at, status, llm_calls, tokens_in, tokens_out, cost_inr, outcome, error) FROM 'csv/agent_runs.csv' WITH (FORMAT csv, HEADER true)
COMMIT;
ANALYZE;
